-- Karen Kim (profileID=11) — ENDORSEMENTS
-- Generated by endorsement_framework.py

-- STEP 1: PHRASE_ENDORSE rows for all Karen Kim phrasings

SELECT p.argumentID, p.phrasingID, 11, 100, 1
FROM PHRASING p
WHERE p.coinedBy = 11
  AND NOT EXISTS (
    SELECT 1 FROM PHRASE_ENDORSE pe
    WHERE pe.profileID = 11 AND pe.argumentID = p.argumentID
  );

-- STEP 2: Endorsement chains (Because / Therefore / Rebuttal)

DELETE FROM ENDORSEMENT WHERE profileID=11 AND targArgID IN (80,89,90,100,103,107,108,110,118,123,134,141,142,145,148,153,154,155,169,175,182,184,193,203,207,217,218,219,230,240,279,293,295,315,316,317,318,320,321,331,333,349,355,356,357,367,368,369,374,378,414,416,463,464,476,477,478,479,480,484,485,486,494,495,496,498,499,500,501,504,505,539,544,546,560,588,591,603,611,612,615,636,654,655,696,697,698,699,700,701,702,745,863,892,894,895,896,897,898,899,909,910,946,954,958,972);


-- STEP 3: Sync PHRASE_ENDORSE active flag with opinion acceptance

UPDATE PHRASE_ENDORSE pe
JOIN OPINION o ON pe.argumentID = o.argumentID AND o.profileID = 11
SET pe.active = o.acceptance
WHERE pe.profileID = 11;

SELECT 'Done: endorsements for profileID=11' AS status;